{
  "outcome": "patch",
  "candidate_reviews": {
    "C001": {
      "decision": "edit",
      "reason": "The field 'Quantity' in StockItem changed from int32 to int64. The code uses int.Parse which returns int32, but the generated property is now long. Must use long.Parse to match the new int64 field type and preserve exact signed int64 quantities as canonical decimal strings."
    },
    "C002": {
      "decision": "unaffected",
      "reason": "entity.Quantity is already long (int64) after regeneration. ToString(CultureInfo.InvariantCulture) on long produces the correct canonical decimal string. No change needed."
    },
    "C003": {
      "decision": "unaffected",
      "reason": "The predicate entity.Quantity > 0 works correctly for int64 (long) as it does for int32. The strict >0 stock predicate is preserved. No change needed."
    },
    "C004": {
      "decision": "unaffected",
      "reason": "InventoryRequest.Quantity remains a string in the JSON input. The record definition does not need to change; only the parsing logic (C001) must handle int64 range."
    }
  },
  "edits": [
    {
      "before": "            var sample = new Simulation.Inventory.StockItem { Sku = request.Sku, Quantity = int.Parse(request.Quantity, CultureInfo.InvariantCulture) };\n",
      "after": "            var sample = new Simulation.Inventory.StockItem { Sku = request.Sku, Quantity = long.Parse(request.Quantity, CultureInfo.InvariantCulture) };\n"
    }
  ],
  "rationale": "Only the construction of the sample StockItem needs updating: the Quantity field is now int64 (long in C#), so parsing must use long.Parse to accept the full int64 range and avoid overflow. The observation path (entity.Quantity.ToString) and predicate (entity.Quantity > 0) already work correctly with long. The InventoryRequest record correctly keeps Quantity as string for JSON canonical decimal representation.",
  "confidence": 0.95,
  "assumptions": [
    "The regenerated StockItem.Quantity property is of type long (int64).",
    "JSON input for Quantity is always a valid canonical decimal string within int64 range.",
    "No other runtime files require changes for this schema migration."
  ]
}
